class Student:
    def __init__(self, name):
        self.name = name
        self.grades = []

    def add_grade(self, grade):
        self.grades.append(grade)

    def average(self):
        return sum(self.grades) / len(self.grades)

    def __str__(self):
        return f"Student: {self.name}, Average: {self.average()}"

alice = Student("Alice")
alice.add_grade(90)
alice.add_grade(95)
alice.add_grade(85)

bob = Student("Bob")
bob.add_grade(80)
bob.add_grade(90)

print(alice)
print(bob)
